          </div>}
        </div>
      </div>
    </div>
  </section>;
}

const COMMIT_SHA_PATTERN = /^[0-9a-f]{40}$/iu;
const SOURCE_HASH_PATTERN = /^[0-9a-f]{64}$/iu;
const REQUIRED_NODE_MAJOR = 24;

export function normalizeOrigin(value) {
  const raw = String(value ?? "").trim();
  if (!raw) throw new Error("Production URL is required.");
  const url = new URL(raw);
  if (url.protocol !== "https:" && url.protocol !== "http:") {
    throw new Error("Production URL must use http or https.");
  }
  return url.origin;
}

export function normalizeCommitSha(value) {
  return String(value ?? "").trim().toLowerCase();
}

export function normalizeSourceHash(value) {
  return String(value ?? "").trim().toLowerCase();
}

export function assessReleaseIntegrity({ expectedSha, expectedSourceHash, health, readiness }) {
  const expected = normalizeCommitSha(expectedSha);
  const actual = normalizeCommitSha(health?.commitSha);
  const expectedSource = normalizeSourceHash(expectedSourceHash);
  const actualSource = normalizeSourceHash(health?.sourceHash);
  const releaseId = String(health?.releaseId ?? "").trim();
  const nodeVersion = String(health?.nodeVersion ?? "").trim();
  const nodeMajor = Number.parseInt(nodeVersion.split(".")[0] ?? "", 10);
  const missing = Array.isArray(readiness?.missing)
    ? readiness.missing.filter((item) => typeof item === "string" && item.trim())
    : [];
  const issues = [];

  if (!COMMIT_SHA_PATTERN.test(expected)) {
    issues.push("expected SHA must be a full 40-character Git commit SHA");
  }
  if (!SOURCE_HASH_PATTERN.test(expectedSource)) {
    issues.push("expected source hash must be a 64-character SHA-256 value");
  }
  if (health?.status !== "ok") {
    issues.push(`health status is ${health?.status ?? "missing"}`);
  }
  if (!actualSource) {
    issues.push("deployed health response is missing sourceHash");
  } else if (SOURCE_HASH_PATTERN.test(expectedSource) && actualSource !== expectedSource) {
    issues.push(`deployed source hash ${actualSource} does not match expected source hash ${expectedSource}`);
  }
  if (actual) {
    if (!COMMIT_SHA_PATTERN.test(actual)) {
      issues.push("deployed commitSha is not a full 40-character Git commit SHA");
    } else if (COMMIT_SHA_PATTERN.test(expected) && actual !== expected) {
      issues.push(`deployed SHA ${actual} does not match expected SHA ${expected}`);
    }
  }
  if (!releaseId) {
    issues.push("deployed health response is missing releaseId");
  }
  if (!nodeVersion) {
    issues.push("deployed health response is missing nodeVersion");
  } else if (nodeMajor !== REQUIRED_NODE_MAJOR) {
    issues.push(`deployed Node.js major ${Number.isFinite(nodeMajor) ? nodeMajor : "invalid"} does not match required major ${REQUIRED_NODE_MAJOR}`);
  }
  if (readiness?.status !== "ready") {
    issues.push(`readiness status is ${readiness?.status ?? "missing"}`);
  }
  if (missing.length > 0) {
    issues.push(`readiness reports missing checks: ${missing.join(", ")}`);
  }

  return {
    ok: issues.length === 0,
    verificationMode: actual ? "commit-sha+source-hash" : "source-hash",
    expectedSha: expected || null,
    actualSha: actual || null,
    expectedSourceHash: expectedSource || null,
    actualSourceHash: actualSource || null,
    releaseId: releaseId || null,
    healthStatus: health?.status ?? null,
    nodeVersion: nodeVersion || null,
    readinessStatus: readiness?.status ?? null,
    missing,
    issues,
  };
}

export async function fetchJson(url, { fetchImpl = globalThis.fetch, timeoutMs = 10_000 } = {}) {
  if (typeof fetchImpl !== "function") throw new Error("fetch implementation is required");
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetchImpl(url, {
      cache: "no-store",
      headers: { accept: "application/json" },
      signal: controller.signal,
    });
    if (!response.ok) throw new Error(`${url} returned HTTP ${response.status}`);
    const body = await response.json();
    if (!body || typeof body !== "object" || Array.isArray(body)) {
      throw new Error(`${url} did not return a JSON object`);
    }
    return body;
  } finally {
    clearTimeout(timer);
  }
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export async function verifyDeployment({
  origin,
  expectedSha,
  expectedSourceHash,
  attempts = 1,
  delayMs = 0,
  fetchImpl = globalThis.fetch,
}) {
  const normalizedOrigin = normalizeOrigin(origin);
  const totalAttempts = Math.max(1, Number.parseInt(String(attempts), 10) || 1);
  const pauseMs = Math.max(0, Number.parseInt(String(delayMs), 10) || 0);
  let lastReport = null;

  for (let attempt = 1; attempt <= totalAttempts; attempt += 1) {
    try {
      const [health, readiness] = await Promise.all([
        fetchJson(`${normalizedOrigin}/api/health`, { fetchImpl }),
        fetchJson(`${normalizedOrigin}/api/readiness`, { fetchImpl }),
      ]);
      lastReport = {
        attempt,
        origin: normalizedOrigin,
        ...assessReleaseIntegrity({ expectedSha, expectedSourceHash, health, readiness }),
      };
    } catch (error) {
      lastReport = {
        attempt,
        origin: normalizedOrigin,
        ok: false,
        verificationMode: null,
        expectedSha: normalizeCommitSha(expectedSha) || null,
        actualSha: null,
        expectedSourceHash: normalizeSourceHash(expectedSourceHash) || null,
        actualSourceHash: null,
        releaseId: null,
        healthStatus: null,
        nodeVersion: null,
        readinessStatus: null,
        missing: [],
        issues: [error instanceof Error ? error.message : String(error)],
      };
    }

    if (lastReport.ok || attempt === totalAttempts) return lastReport;
    if (pauseMs > 0) await sleep(pauseMs);
  }

  return lastReport;
}

import type { PreparedText, ProtectedKind, ProtectedSpan } from "./types";

interface Candidate {
  kind: ProtectedKind;
  start: number;
  end: number;
  value: string;
}

const PATTERNS: Array<{ kind: ProtectedKind; regex: RegExp }> = [
  { kind: "code", regex: /`[^`\n]{1,500}`/g },
  { kind: "url", regex: /https?:\/\/[^\s<>"'\])}]+/gi },
  { kind: "email", regex: /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi },
  { kind: "quote", regex: /“[^”\n]{1,800}”|"[^"\n]{1,800}"/g },
  { kind: "citation", regex: /\[[0-9,;\s–—-]+\]|\([A-Z][A-Za-z'’-]+(?:\s+et al\.)?,?\s+\d{4}[a-z]?\)/g },
  { kind: "date", regex: /\b(?:\d{4}-\d{1,2}-\d{1,2}|\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}|(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+\d{1,2},?\s+\d{4})\b/gi },
  { kind: "number", regex: /(?<![\p{L}\p{N}_])(?:[+-]\s*)?(?:[$€£¥]\s*)?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?%?(?![\p{L}\p{N}_])/gu },
];

const MULTI_ENTITY = /\b(?:[A-Z][\p{Ll}\p{M}'’.-]{1,}|[A-Z]{2,})(?:\s+(?:(?:of|the|and|&|for)\s+)?(?:[A-Z][\p{Ll}\p{M}'’.-]{1,}|[A-Z]{2,})){1,4}\b/gu;
const CAMEL_ENTITY = /\b[A-Z][\p{Ll}\p{M}]{1,}[A-Z][\p{L}\p{M}\p{N}]*\b/gu;
const ACRONYM_ENTITY = /\b[A-Z]{2,10}\b/g;
const STRUCTURAL_LEADERS = new Set(["On", "In", "At", "From", "To", "For", "By", "With", "As", "This", "That", "These", "Those", "We", "I"]);

function matches(regex: RegExp, text: string, kind: ProtectedKind): Candidate[] {
  regex.lastIndex = 0;
  const found: Candidate[] = [];
  for (const match of text.matchAll(regex)) {
    if (match.index === undefined) continue;
    found.push({ kind, start: match.index, end: match.index + match[0].length, value: match[0] });
  }
  return found;
}

function reliableMultiEntities(text: string) {
  return matches(MULTI_ENTITY, text, "entity").filter(candidate => {
    const tokens = candidate.value.split(/\s+/u);
    // Avoid weak sentence-structure collisions such as "On August" stealing the
    // higher-confidence date "August 31, 2026". Longer names such as
    // "The New York Times" remain eligible because their evidence is stronger.
    return !STRUCTURAL_LEADERS.has(tokens[0]) || tokens.length >= 3;
  });
}

function candidatesFor(text: string): Candidate[] {
  const candidates: Candidate[] = [];
  for (const { kind, regex } of PATTERNS) candidates.push(...matches(regex, text, kind));
  candidates.push(...reliableMultiEntities(text));
  candidates.push(...matches(CAMEL_ENTITY, text, "entity"));
  candidates.push(...matches(ACRONYM_ENTITY, text, "entity"));
  return candidates;
}

function chooseNonOverlapping(candidates: Candidate[]) {
  const chosen: Candidate[] = [];
  const sorted = [...candidates].sort((a, b) => a.start - b.start || (b.end - b.start) - (a.end - a.start));
  for (const candidate of sorted) {
    const overlaps = chosen.some((item) => candidate.start < item.end && item.start < candidate.end);
    if (!overlaps) chosen.push(candidate);
  }
  return chosen.sort((a, b) => a.start - b.start);
}

export function prepareProtectedText(text: string): PreparedText {
  const selected = chooseNonOverlapping(candidatesFor(text));
  const spans: ProtectedSpan[] = selected.map((item, id) => ({ ...item, id, token: `[[PROTECTED_${String(id).padStart(4, "0")}]]` }));
  let cursor = 0;
  let protectedText = "";
  for (const span of spans) { protectedText += text.slice(cursor, span.start) + span.token; cursor = span.end; }
  protectedText += text.slice(cursor);
  return { original: text, protectedText, spans };
}

export function tokenOccurrenceCount(text: string, token: string) { return text.split(token).length - 1; }
export function restoreProtectedText(text: string, spans: ProtectedSpan[]) { let restored = text; for (const span of spans) restored = restored.split(span.token).join(span.value); return restored; }
export function extractInvariantValues(text: string) { const prepared = prepareProtectedText(text); return prepared.spans.filter((span) => span.kind !== "quote" && span.kind !== "code" && span.kind !== "citation").map((span) => `${span.kind}:${span.value}`).sort(); }

import { z } from "zod";
import { verifyTurnstile } from "@/lib/abuse/turnstile";
import { getRequestIdentity } from "@/lib/auth/identity";
import { getSubscriptionPlan, type SubscriptionPlanId } from "@/lib/billing/subscriptions";
import { getStripe } from "@/lib/billing/stripe";
import { createAdminClient } from "@/lib/supabase/admin";
import { apiError, apiOk, parseJson, requestContext, retryAfter } from "@/lib/server/api";
import { publicAppOrigin } from "@/lib/server/env";
import { configuredLimit, consumeRateLimit } from "@/lib/server/rate-limit";
import { logEvent, requestSubjectKey } from "@/lib/server/observability";

export const runtime = "nodejs";
const schema = z.object({ planId: z.enum(["plus_monthly", "pro_monthly", "studio_monthly"]), challengeToken: z.string().max(2048).optional() });

function customerIdFrom(value: unknown) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const id = (value as { stripe_customer_id?: unknown }).stripe_customer_id;
  return typeof id === "string" && /^cus_/u.test(id) ? id : null;
}

export async function POST(request: Request) {
  const context = requestContext(request, "/api/billing/subscription-checkout");
  try {
    const identity = await getRequestIdentity();
    if (!identity || identity.isAnonymous) return apiError(context, "registered_account_required", "Sign in with a registered account before starting a monthly plan.", 401);

    const subject = requestSubjectKey(request, identity.userId);
    const limit = consumeRateLimit("subscription-checkout", subject, configuredLimit("RATE_LIMIT_CHECKOUT_PER_MINUTE", 4), 60_000);
    if (!limit.allowed) return apiError(context, "rate_limited", "Too many checkout requests. Try again shortly.", 429, retryAfter(limit.retryAfterSeconds));

    const { planId, challengeToken } = await parseJson(request, schema, 4_096);
    const challenge = await verifyTurnstile(challengeToken, "account");
    if (!challenge.ok) {
      logEvent("bot_challenge_failed", { requestId: context.requestId, route: context.route, userIdHash: subject, reason: challenge.reason ?? "unknown" });
      return apiError(context, challenge.reason === "not_configured" ? "bot_protection_unavailable" : "bot_challenge_failed", challenge.reason === "not_configured" ? "Bot protection is not configured." : "Bot verification is required.", challenge.reason === "not_configured" ? 503 : 403);
    }

    const plan = getSubscriptionPlan(planId as SubscriptionPlanId);
    const origin = publicAppOrigin(request);
    const { data: linkedCustomer } = await createAdminClient().rpc("billing_get_stripe_customer", { p_user_id: identity.userId });
    const customer = customerIdFrom(linkedCustomer);

    const session = await getStripe().checkout.sessions.create({
      mode: "subscription",
      line_items: [{ price: plan.priceId, quantity: 1 }],
      client_reference_id: identity.userId,
      ...(customer ? { customer } : {}),
      billing_address_collection: "required",
      metadata: { subscription_plan_id: plan.id, user_id: identity.userId },
      subscription_data: { metadata: { subscription_plan_id: plan.id, user_id: identity.userId } },
      success_url: `${origin}/account?subscription=success`,
      cancel_url: `${origin}/pricing?subscription=cancelled`,
    }, { idempotencyKey: `subscription-checkout:${identity.userId}:${plan.id}` });

    if (!session.url) throw new Error("missing_checkout_url");
    logEvent("subscription_checkout_created", { requestId: context.requestId, userIdHash: subject, planId: plan.id, existingCustomer: Boolean(customer) });
    return apiOk(context, { url: session.url, plan: { id: plan.id, credits: plan.credits, monthlyCents: plan.monthlyCents, testMode: true } });
  } catch {
    return apiError(context, "subscription_checkout_unavailable", "Monthly checkout is not available.", 503);
  }
}

const $ = (id) => document.getElementById(id);
const fields = ["apiKey", "apiBase", "mode", "intensity", "purpose"];

async function activeTab() {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  return tab;
}

function setStatus(message, error = false) {
  $("status").textContent = message;
  $("status").className = error ? "status error" : "status";
}

async function loadSettings() {
  const saved = await chrome.storage.local.get(fields);
  $("apiKey").value = saved.apiKey || "";
  $("apiBase").value = saved.apiBase || "https://provenance-cleaner.vercel.app";
  $("mode").value = saved.mode || "parity";
  $("intensity").value = saved.intensity || "balanced";
  $("purpose").value = saved.purpose || "general";
}

async function saveSettings() {
  const payload = Object.fromEntries(fields.map((id) => [id, $(id).value.trim()]));
  await chrome.storage.local.set(payload);
  setStatus("Settings saved. Content is not stored.");
}

async function sendToPage(message) {
  const tab = await activeTab();
  if (!tab?.id) throw new Error("No active tab.");
  return chrome.tabs.sendMessage(tab.id, message);
}

async function rewriteSelection() {
  setStatus("Reading selected text…");
  const selected = await sendToPage({ type: "selection" });
  if (!selected?.ok || !selected.text) throw new Error(selected?.reason || "Select text first.");
  if (selected.text.trim().length < 20) throw new Error("Select at least 20 characters.");

  const apiKey = $("apiKey").value.trim();
  if (!apiKey) throw new Error("Add a developer API key first.");
  const base = $("apiBase").value.trim().replace(/\/$/u, "");
  const body = {
    operationId: crypto.randomUUID(),
    text: selected.text,
    mode: $("mode").value,
    intensity: $("intensity").value,
    purpose: $("purpose").value,
  };

  setStatus("Running protected rewrite…");
  const response = await fetch(`${base}/api/v1/transform`, {
    method: "POST",
    headers: { "content-type": "application/json", authorization: `Bearer ${apiKey}` },
    body: JSON.stringify(body),
  });
  const payload = await response.json();
  if (!response.ok) throw new Error(payload?.error?.message || payload?.error || "Rewrite failed.");

  $("output").value = payload.text;
  $("outputBox").hidden = false;
  if (selected.editable) {
    const replaced = await sendToPage({ type: "replace", text: payload.text });
    if (!replaced?.ok) throw new Error(replaced?.reason || "Result was generated but could not be placed in the page.");
    setStatus(`Validated and replaced in page · ${payload.purpose}/${payload.intensity}. Undo is available.`);
  } else {
    setStatus("Validated result is ready. The original selection is read-only, so copy the result instead.");
  }
}

$("rewrite").addEventListener("click", () => rewriteSelection().catch((error) => setStatus(error.message, true)));
$("undo").addEventListener("click", () => sendToPage({ type: "undo" }).then((result) => {
  if (!result?.ok) throw new Error(result?.reason || "Could not undo.");
  setStatus("Last in-page rewrite undone.");
}).catch((error) => setStatus(error.message, true)));
$("save").addEventListener("click", () => saveSettings().catch((error) => setStatus(error.message, true)));
$("copy").addEventListener("click", () => navigator.clipboard.writeText($("output").value).then(() => setStatus("Result copied.")).catch(() => setStatus("Could not copy result.", true)));
void loadSettings();

"use client";

import { useCallback, useState } from "react";
