import { z } from "zod";
import { authenticateDeveloperRequest } from "@/lib/developer-api";
import { sanitizeText, scanText } from "@/lib/provenance/unicode";
import { ApiRequestError, apiError, apiOk, parseJson, requestContext, retryAfter } from "@/lib/server/api";
import { wordBucketKey } from "@/lib/server/buckets";
import { logEvent, requestSubjectKey } from "@/lib/server/observability";
import { configuredLimit, consumeRateLimit } from "@/lib/server/rate-limit";
import { countWords } from "@/lib/product-contract";

const bodySchema = z.object({
  text: z.string().max(250_000),
  sanitize: z.enum(["none", "conservative", "aggressive"]).default("none"),
});

export async function POST(request: Request) {
  const context = requestContext(request, "/api/v1/scan");
  let identity;
  try { identity = await authenticateDeveloperRequest(request); }
  catch { return apiError(context, "developer_api_unavailable", "Developer API authentication is unavailable.", 503); }
  if (!identity) return apiError(context, "invalid_api_key", "A valid Bearer API key is required.", 401, { "www-authenticate": "Bearer" });

  const subject = requestSubjectKey(request, identity.keyId);
  const limit = consumeRateLimit("developer-scan", subject, configuredLimit("RATE_LIMIT_DEVELOPER_SCAN_PER_MINUTE", 60), 60_000);
  if (!limit.allowed) return apiError(context, "rate_limited", "Developer scan rate limit exceeded.", 429, retryAfter(limit.retryAfterSeconds));

  try {
    const body = await parseJson(request, bodySchema, 300_000);
    const receipt = scanText(body.text);
    const sanitation = body.sanitize === "none" ? null : sanitizeText(body.text, body.sanitize);
    logEvent("developer_scan", {
      requestId: context.requestId,
      developerKeyHash: subject,
      sourceWordBucket: wordBucketKey(countWords(body.text)),
      findings: receipt.summary.total,
      sanitizeMode: body.sanitize,
    });
    return apiOk(context, { receipt, sanitation }, 200, { "cache-control": "no-store" });
  } catch (error) {
    if (error instanceof ApiRequestError) return apiError(context, error.code, error.message, error.status);
    return apiError(context, "scan_failed", "The scan could not be completed.", 500);
  }
}

import { describe, expect, it } from "vitest";
import { MAX_FILE_BYTES } from "../src/lib/product-contract";
import { planSanitizationJob, SanitizationContractError } from "../src/lib/sanitization";

describe("unified sanitization job contract", () => {
  it("keeps inspection free and local", () => {
    const plan = planSanitizationJob({ kind: "text", intent: "inspect", text: "hello" });
    expect(plan.credits).toBe(0);
    expect(plan.stages).toEqual(["inspect", "receipt"]);
    expect(plan.serverAuthoritativeBilling).toBe(false);
  });

  it("routes text and TXT sanitation through shared word-based economics", () => {
    expect(planSanitizationJob({ kind: "text", intent: "sanitize", text: "one ".repeat(1001) }).credits).toBe(2);
    expect(planSanitizationJob({ kind: "txt", intent: "sanitize", text: "one ".repeat(1001) }).credits).toBe(2);
  });

  it("routes DOCX/PNG/JPEG sanitation as one-credit jobs", () => {
    for (const kind of ["docx", "png", "jpeg"] as const) expect(planSanitizationJob({ kind, intent: "sanitize", bytes: MAX_FILE_BYTES }).credits).toBe(1);
  });

  it("rejects oversize files and rewrites before billing", () => {
    expect(() => planSanitizationJob({ kind: "png", intent: "sanitize", bytes: MAX_FILE_BYTES + 1 })).toThrow(SanitizationContractError);
    const tooMany = Array.from({ length: 8001 }, () => "word").join(" ");
    expect(() => planSanitizationJob({ kind: "text", intent: "rewrite", text: tooMany })).toThrow(/8,000 words/i);
  });

  it("blocks destructive file sanitation when signed provenance is present", () => {
    expect(() => planSanitizationJob({ kind: "jpeg", intent: "sanitize", bytes: 100, hasProvenance: true })).toThrow(/provenance/i);
  });
});

import { createAdminClient } from "@/lib/supabase/admin";
import { apiOk, requestContext } from "@/lib/server/api";
import { readinessSummary } from "@/lib/server/env";

export const dynamic = "force-dynamic";

function record(value:unknown){return value&&typeof value==="object"&&!Array.isArray(value)?value as Record<string,unknown>:null;}

export async function GET(request:Request){
  const context=requestContext(request,"/api/admin/readiness");
  const env=readinessSummary(request);

  let adminStatus:Record<string,unknown>|null=null;
  try{const {data,error}=await createAdminClient().rpc("ops_admin_status");if(!error)adminStatus=record(data);}catch{adminStatus=null;}

  const ownerConfigured=adminStatus?.ownerConfigured===true;
  const bootstrapConfigured=env.checks.adminOwnerBootstrap?.configured===true;
  const ready=ownerConfigured||bootstrapConfigured;

  return apiOk(context,{
    status:ready?"ready":"not_ready",
    checks:{
      adminOwner:{configured:ready,required:true},
      adminOwnerProvisioned:{configured:ownerConfigured,required:false},
      adminOwnerBootstrap:{configured:bootstrapConfigured,required:false},
    },
    missing:ready?[]:["adminOwner"],
    admin:{ready,ownerConfigured,bootstrapConfigured},
  },ready?200:503,{"cache-control":"no-store"});
}

